import html
# Curated from official agency/provider pages reviewed 2026-10-14.
# category, title, url, description, useful tip
RESOURCES=[
('Property & taxes','Richland County property records & maps','https://www.richlandcountysc.gov/Property-Business/Mapping-and-Records','Find property records and GIS mapping from the county’s official directory.','Start with the exact street address or tax map number. Map lines are not a boundary survey.'),
('Property & taxes','Lexington County property search','https://lex-co.sc.gov/services/property-tax-data-search','Look up county property-tax records before comparing ownership costs.','A seller’s bill may reflect exemptions or classifications that do not apply to your purchase.'),
('Property & taxes','Lexington County online maps','https://www.lex-co.sc.gov/departments/planning-gis/gis-disclaimer/online-mapping','Explore the county’s online mapping tools for a property and its surroundings.','Use maps for orientation; verify boundaries and restrictions through the appropriate records and professionals.'),
('Property & taxes','Richland County legal residence','https://www.richlandcountysc.gov/Property-Business/Property-Valuation/Legal-Residence','Read the county’s requirements and application information for legal-residence assessment.','Confirm your own eligibility and application steps with the assessor. Do not assume a seller’s status transfers.'),
('Property & taxes','Lexington County legal residence','https://lex-co.sc.gov/departments/assessor/tax-faqs/legal-residence-discount','Understand the county’s legal-residence assessment and where to start an application.','The 4% figure is an assessment ratio, not your final property-tax rate. Ask the assessor about your property.'),
('Utilities & services','Columbia Water: new or transfer service','https://columbiascwater.net/new-transfer-service/','Start the process to open or transfer a Columbia Water account.','Confirm that Columbia Water serves your address and coordinate the requested start date with closing.'),
('Utilities & services','Dominion Energy: start, stop or move','https://www.dominionenergy.com/South-Carolina/Start-Stop-Service','Find South Carolina electric and natural-gas account options.','Check service availability for the exact address. A city name alone does not identify your provider.'),
('Utilities & services','Mid-Carolina Electric: start service','https://www.mcecoop.com/my-account/start-service/','Check the cooperative’s service map and apply for residential electricity.','Enter your address in the provider’s map before submitting an application.'),
('Utilities & services','Richland County trash & recycling','https://www.richlandcountysc.gov/Utilities-Services/Trash-and-Recycling','Find county waste and recycling information and service contacts.','Verify whether collection is handled by the county, municipality, or another provider at your address.'),
('Utilities & services','Lexington County solid waste','https://lex-co.sc.gov/departments/swm','Find disposal, recycling, and solid-waste department information.','Check accepted materials and the rules for your collection service before putting out moving debris.'),
('Schools & learning','Richland School District One','https://www.richlandone.org/','Start with the district for enrollment, school information, and attendance questions.','Ask the district to confirm assignment for your full property address.'),
('Schools & learning','Richland School District Two','https://www.richland2.org/','Explore district schools, family resources, and enrollment information.','Verify attendance zones and any program application requirements directly with the district.'),
('Schools & learning','Lexington County School District One','https://www.lexington1.net/','Find official school, student-services, and family information.','A Lexington mailing address does not by itself confirm this district or a specific school.'),
('Schools & learning','Lexington School District Two','https://www.lex2.org/','Access school and enrollment resources from Lexington Two.','Confirm school assignment with the district before making a property decision.'),
('Schools & learning','Lexington-Richland School District Five','https://www.lexrich5.org/','Explore school and enrollment information for District Five.','Irmo and Chapin area names do not substitute for an address-level school assignment check.'),
('Schools & learning','Richland Library','https://www.richlandlibrary.com/','Explore library locations, events, collections, and community resources.','Check card eligibility and the location nearest your new home.'),
('Schools & learning','Lexington County Library','https://lexcolibrary.com/','Find branches, library services, and local programming.','Look up branch details and library-card requirements before your first visit.'),
('Home & lake checks','FEMA Flood Map Service Center','https://msc.fema.gov/portal/search','Search the official flood-map resource by property address.','Discuss the property with your insurance provider and local floodplain office; maps do not capture every source of flood risk.'),
('Home & lake checks','Lake Murray shoreline & dock information','https://www.dominionenergy.com/About/Lakes-and-Recreation/Lake-Murray-SC','Find lake-management information, shoreline permits, and lake-use resources.','Ask about the specific property’s dock and shoreline records. A visible dock does not establish permit status.'),
('Home & lake checks','SC Residential Builders Commission','https://www.llr.sc.gov/res/','Find official licensing and consumer information for residential builders and home inspectors.','Verify the appropriate license or registration and ask separately about insurance and scope of work.'),
('Moving & everyday life','SCDMV: moving to South Carolina','https://www.scdmvonline.com/Driver-Services/Moving-to-SC','Find official driver-license and ID guidance for new residents.','Review current deadlines, required documents, and any exceptions that apply to your situation.'),
('Moving & everyday life','SCDMV: vehicle title & registration','https://www.scdmvonline.com/Vehicle-Owners/Moving-To-SC','Review the steps to transfer a vehicle’s title and registration to South Carolina.','Check the county property-tax step before visiting the DMV.'),
('Moving & everyday life','USPS mail forwarding','https://www.usps.com/manage/forward.htm','Use the Postal Service’s official guidance for forwarding mail and changing your address.','Update important accounts directly as well; forwarding is not a substitute for notifying each organization.'),
('Moving & everyday life','South Carolina emergency preparedness','https://www.scemd.org/','Find state preparedness resources and emergency information.','Make an address-specific household plan and learn your local alert options.'),
('Moving & everyday life','Lexington Health','https://lexhealth.com/','Explore the health system’s locations, providers, and services.','Check current appointment availability and insurance participation directly with the provider.'),
('Moving & everyday life','Experience Columbia SC','https://www.experiencecolumbiasc.com/','Explore neighborhoods, local attractions, and things to do around Columbia.','Use it to plan a scouting visit and explore beyond the homes on your tour list.'),
('Moving & everyday life','Lake Murray Country','https://www.lakemurraycountry.com/','Discover regional recreation, events, and lake-area destinations.','Compare public recreation access with the private access advertised for a particular property.'),
('Local government','Richland County services','https://www.richlandcountysc.gov/Home','Find county departments, services, and public information.','Use your parcel’s jurisdiction rather than its mailing city to identify the right office.'),
('Local government','Lexington County services','https://lex-co.sc.gov/services','Access the county’s online-service directory, including property and recorded-document tools.','Have the property address and tax map number handy when contacting an office.'),
('Local government','City of Columbia','https://columbiasc.gov/','Find municipal departments, public information, and city services.','Confirm whether a property is inside city limits before assuming municipal services apply.')]
RESOURCE_FAQS=[('Where can I find property records for a Columbia-area home?','Start with the county where the parcel is located. Use Richland County’s mapping and records directory or Lexington County’s property search and mapping tools. Search by the exact address or tax map number; the mailing city alone may not identify the jurisdiction.'),('How do I know which utility provider serves my new home?','Confirm service with the provider using the complete address. This hub links to Columbia Water, Dominion Energy, and Mid-Carolina Electric as starting points, but they are not a complete list of every Midlands provider.'),('Does a home’s mailing address tell me its school assignment?','No. Confirm attendance boundaries, enrollment requirements, and any program-specific rules directly with the school district using the exact property address.'),('Where do I check Lake Murray dock and shoreline information?','Start with Dominion Energy’s Lake Murray page for lake-management and permitting resources, then ask about the specific property’s records. Verify any advertised access or dock rights before relying on them.'),('Is South Carolina’s 4% legal-residence figure the property-tax rate?','No. It is an assessment ratio for a qualifying legal residence, not the final tax rate. Review the relevant county assessor’s current requirements and ask for property-specific guidance.')]
def resource_body(intro,btn,faqblock):
 categories=list(dict.fromkeys(x[0] for x in RESOURCES))
 body=intro('THE MIDLANDS FIELD GUIDE','Less searching.<br><em>More settling in.</em>','The right local link, right when you need it. A practical resource hub for buying, moving, and feeling at home in Columbia, Lexington, and the South Carolina Midlands.')
 body+='''<section class="wrap resource-start"><div><p class="eyebrow">START WITH YOUR ADDRESS</p><h2>One address.<br>Several things to verify.</h2><p>A mailing city, county, school district, and utility territory can have different boundaries. Start with the exact address, then confirm each service with its provider.</p></div><div class="quicklinks"><a href="#resource-directory" data-preset="Property & taxes">01 <span>Look up a property</span> ↗</a><a href="#resource-directory" data-preset="Utilities & services">02 <span>Get the essentials connected</span> ↗</a><a href="#resource-directory" data-preset="Schools & learning">03 <span>Find school & library resources</span> ↗</a><a href="#moving-checklist">04 <span>Work through your moving list</span> ↓</a></div></section>'''
 body+='''<section class="wrap section" id="resource-directory"><div class="sectionhead"><div><p class="eyebrow">BOOKMARK THIS FOR LATER</p><h2>Your local<br><em>shortcuts.</em></h2></div><p>Official agency and provider links, with a short explanation of when to use each. No signup required.</p></div><div class="resource-controls" hidden><label for="resource-search">Find a resource<input id="resource-search" type="search" placeholder="Try water, property taxes, schools, or docks…"></label><label for="resource-category">Browse by topic<select id="resource-category"><option value="all">All topics</option>'''+''.join(f'<option>{html.escape(c)}</option>' for c in categories)+'''</select></label><button class="button light" id="resource-reset" type="button">Reset</button></div><p id="resource-count" role="status" class="fine">30 resources · Sources reviewed October 14, 2026</p><div class="resource-grid">'''
 for cat,title,url,desc,tip in RESOURCES:
  body+=f'<article class="resource-card" data-category="{html.escape(cat,quote=True)}"><span class="eyebrow">{html.escape(cat)}</span><h3><a href="{html.escape(url,quote=True)}">{html.escape(title)} <span aria-hidden="true">↗</span></a></h3><p>{html.escape(desc)}</p><div class="resource-tip"><strong>Before you go</strong><p>{html.escape(tip)}</p></div><a class="textlink" href="{html.escape(url,quote=True)}">Visit official resource ↗<span class="sr-only">: {html.escape(title)}</span></a></article>'
 body+='''</div><div id="resource-empty" hidden><h3>No matching resources yet.</h3><p>Try a shorter search or choose “All topics.” James can also help you find the right starting point.</p>'''+btn('Ask James','/contact/')+'''</div><p class="fine resource-note">This is a curated starting point, not an exhaustive directory or a list of endorsed vendors. Service areas, requirements, and links may change. Confirm current details directly with the agency or provider. For an emergency, call 911.</p></section><section class="checklistband" id="moving-checklist"><div class="wrap section"><div class="sectionhead"><div><p class="eyebrow">YOUR NEXT CHAPTER, ONE STEP AT A TIME</p><h2>The moving-in<br><em>shortlist.</em></h2></div><div><p>Check off the essentials as you go. Your progress stays in this browser when local storage is available.</p><button id="print-checklist" class="button light" type="button" hidden>Print checklist ↗</button></div></div><div class="checklist-grid">'''
 tasks=[('Before you commit',['Confirm county and municipal boundaries for the exact address.','Review property records, flood information, and any HOA documents.','Verify school assignments directly with the relevant district.','For lake property, investigate access, dock records, and shoreline requirements.']),('Before moving day',['Confirm electricity, gas, water, sewer, internet, and trash providers.','Arrange service start dates and confirm access for installations.','Coordinate the final walkthrough, keys, and closing details with your team.','Set up mail forwarding and update important accounts directly.']),('Once you have the keys',['Review legal-residence application steps with your county assessor.','Check current DMV requirements if you are moving from another state.','Learn collection schedules and accepted recycling materials.','Locate shutoff valves, test alarms, and set up your household emergency plan.'])]
 for j,(title,items) in enumerate(tasks):
  body+=f'<div class="checklist-column"><p class="eyebrow">0{j+1}</p><h3>{title}</h3>'
  for k,t in enumerate(items):body+=f'<label class="task"><input type="checkbox" data-task="{j}-{k}"><span>{t}</span></label>'
  body+='</div>'
 body+='''</div><p class="fine" id="checklist-status" role="status"></p><button id="clear-checklist" type="button" class="textbutton" hidden>Clear checked items</button></div></section><section class="wrap section split faqsection"><div><p class="eyebrow">LOCAL QUESTIONS, CLEAR STARTING POINTS</p><h2>A little context.<br><em>A lot less guesswork.</em></h2><p>James can help you organize the questions. The agency or provider confirms the answer for your address.</p>'''+btn('Talk with James','/contact/')+'</div>'+faqblock(RESOURCE_FAQS)+'</section>'
 return body
